<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit,Authorization,Staff};
final class Registration {
 public static function snapshot(\PDO $p,int $staff):array {
  $s=Database::query($p,'SELECT s.staff_identity_id,s.full_name,s.organisation_id,s.facility_id,s.unit_id,s.profession_id,s.position_id,s.grade_id,s.employment_status_id,o.name AS organisation_name FROM staff_profiles s JOIN organisations o ON o.id=s.organisation_id WHERE s.staff_identity_id=? AND o.is_active=1',[$staff])->fetch();if(!$s)throw new \RuntimeException('Profil/organisasi staf tidak aktif.');
  $s['ancestor_ids']=array_map('intval',Database::query($p,'SELECT ancestor_id FROM organisation_hierarchy WHERE descendant_id=?',[$s['organisation_id']])->fetchAll(\PDO::FETCH_COLUMN));foreach(['profession','position','grade'] as $k)$s[$k.'_name']=$s[$k.'_id']?Database::query($p,'SELECT name FROM master_data WHERE id=?',[$s[$k.'_id']])->fetchColumn():null;return $s;
 }
 public static function eligibility(\PDO $p,array $r,array $c,array $s):array {
  $scope=[$r['owner_organisation_id']];if($c['scope']==='DISTRICT_WIDE'){$pkd=Programmes::district($p,(int)$r['owner_organisation_id']);if(!$pkd)throw new \RuntimeException('Organisasi tiada PKD.');$scope=[$pkd];}elseif($c['scope']==='TARGETED')$scope=$c['audience'];
  if(!array_intersect(array_map('intval',$scope),$s['ancestor_ids']))throw new \RuntimeException('Di luar scope program.');if($c['registration_mode']==='TARGETED'&&!array_intersect($c['audience'],$s['ancestor_ids']))throw new \RuntimeException('Bukan kumpulan sasaran.');
  foreach($c['eligibility'] as $cat=>$ids)if($ids&&!in_array((int)($s[$cat.'_id']??0),$ids,true))throw new \RuntimeException('Tidak memenuhi syarat '.$cat.'.');return ['eligible'=>true,'revision_id'=>$r['published_revision_id'],'evaluated_at'=>gmdate('c')];
 }
 private static function rows(\PDO $p,int $id):array {return Database::query($p,"SELECT snapshot_json FROM training_registrations WHERE programme_id=? AND status IN ('PENDING','CONFIRMED') FOR UPDATE",[$id])->fetchAll(\PDO::FETCH_COLUMN);}
 private static function matchQuota(array $q,array $s):bool {return $q['kind']==='profession'?(int)$s['profession_id']===$q['id']:in_array($q['id'],$s['ancestor_ids'],true);}
 public static function available(\PDO $p,int $id,array $c,array $s):bool {$rows=self::rows($p,$id);if(count($rows)>=$c['capacity'])return false;foreach($c['quotas'] as $q)if(self::matchQuota($q,$s)){$n=0;foreach($rows as $json)if(self::matchQuota($q,json_decode($json,true,512,JSON_THROW_ON_ERROR)))$n++;if($n>=$q['limit'])return false;}return true;}
 public static function verifyCapacity(\PDO $p,int $id,array $c):void {$rows=self::rows($p,$id);if(count($rows)>$c['capacity'])throw new \RuntimeException('Kapasiti di bawah tempat ditempah.');foreach($c['quotas'] as $q){$n=0;foreach($rows as $json)if(self::matchQuota($q,json_decode($json,true,512,JSON_THROW_ON_ERROR)))$n++;if($n>$q['limit'])throw new \RuntimeException('Kuota di bawah tempat ditempah.');}}
 public static function change(\PDO $p,array $r,array $reg,int $u,string $status,string $reason):void {
  Database::query($p,'UPDATE training_registrations SET status=? WHERE id=?',[$status,$reg['id']]);Database::query($p,'INSERT INTO training_registration_history(registration_id,actor_id,old_status,new_status,reason) VALUES(?,?,?,?,?)',[$reg['id'],$u,$reg['status']??null,$status,Core::text($reason,500)]);$hid=(int)$p->lastInsertId();Audit::record($p,'registration.status_changed',$u,(int)$r['owner_organisation_id'],(string)$reg['id'],'training',$reason,['status'=>$reg['status']??null],['status'=>$status,'programme_id'=>$r['id']]);$uid=Database::query($p,'SELECT id FROM users WHERE staff_identity_id=? AND is_active=1',[$reg['staff_identity_id']])->fetchColumn();if($uid)Events::emit($p,(int)$r['id'],(int)$uid,'registration:'.$hid,'Pendaftaran program #'.$r['id'].': '.$status.'. '.$reason);
 }
 public static function register(\PDO $p,int $u,int $id,?int $staff=null,string $source='SELF',?string $token=null,?string $linkKey=null):int {
  return Core::tx($p,function()use($p,$u,$id,$staff,$source,$token,$linkKey){$actor=Policy::actor($p,$u);$r=Policy::programme($p,$id,true);if(!$r['is_published']||$r['is_cancelled'])throw new \RuntimeException('Program belum diterbitkan.');$c=Policy::config($p,$r,true);if($linkKey!==null&&(int)Tokens::resolve($p,$linkKey,true)['programme_id']!==$id)throw new \RuntimeException('Pautan program tidak sepadan.');$self=$staff===null;$staff??=(int)$actor['staff_identity_id'];
   if($self){if(!Authorization::super($p,$u)&&!Authorization::allowed($p,$u,'training.registrations.self',(int)$actor['organisation_id']))throw new \RuntimeException('Akses peserta Training belum diberikan.');if(!in_array($source,['SELF','WALK_IN'],true))throw new \RuntimeException('Sumber tidak sah.');}
   else{Policy::require($p,$u,'participants.assign',$r);Staff::get($p,$u,$staff);if(!in_array($source,['ADMIN_ASSIGNED','WALK_IN'],true))throw new \RuntimeException('Sumber assignment tidak sah.');}
   $now=gmdate('Y-m-d H:i:s');if($source==='WALK_IN'){if(!$c['walkin_enabled']||$now<$c['start_at']||$now>$c['end_at'])throw new \RuntimeException('Walk-in tidak dibuka.');if(!$self)Policy::require($p,$u,'registrations.walkin',$r);}elseif($now<$c['open_at']||$now>$c['close_at'])throw new \RuntimeException('Pendaftaran belum dibuka/telah ditutup.');
   $s=self::snapshot($p,$staff);$eval=self::eligibility($p,$r,$c,$s);$old=Database::query($p,'SELECT * FROM training_registrations WHERE programme_id=? AND staff_identity_id=? FOR UPDATE',[$id,$staff])->fetch();if($old&&in_array($old['status'],['PENDING','CONFIRMED','WAITLISTED'],true))return (int)$old['id'];
   if($self&&$c['registration_mode']==='ADMIN_ASSIGNED')throw new \RuntimeException('Program melalui assignment admin sahaja.');
   $invite=null;if($self&&$c['registration_mode']==='INVITATION_ONLY'){$invite=Tokens::invitation($p,$u,$id,$token??'',true);if((int)$invite['staff_identity_id']!==$staff)throw new \RuntimeException('Jemputan bukan untuk staf ini.');}
   $account=Database::query($p,'SELECT id FROM users WHERE staff_identity_id=? AND is_active=1',[$staff])->fetchColumn();$status=self::available($p,$id,$c,$s)?($c['approval_mode']==='AUTO'&&$account?'CONFIRMED':'PENDING'):($c['waiting_list']?'WAITLISTED':'FULL');if($status==='FULL')throw new \RuntimeException('Kuota/kapasiti penuh.');$seq=$status==='WAITLISTED'?(int)Database::query($p,'SELECT COALESCE(MAX(wait_sequence),0)+1 FROM training_registrations WHERE programme_id=?',[$id])->fetchColumn():null;
   $vals=[$status,$source,$seq,json_encode($s,JSON_THROW_ON_ERROR),json_encode($eval,JSON_THROW_ON_ERROR),$self?null:$u];
   if($old){Database::query($p,'UPDATE training_registrations SET status=?,source=?,wait_sequence=?,snapshot_json=?,eligibility_json=?,assigned_by=? WHERE id=?',[...$vals,$old['id']]);$reg=$old;}else{Database::query($p,'INSERT INTO training_registrations(programme_id,staff_identity_id,status,source,wait_sequence,snapshot_json,eligibility_json,assigned_by) VALUES(?,?,?,?,?,?,?,?)',[$id,$staff,...$vals]);$reg=['id'=>(int)$p->lastInsertId(),'staff_identity_id'=>$staff,'status'=>null];}
   self::change($p,$r,$reg,$u,$status,'Registration '.$source);if($invite)Database::query($p,'UPDATE training_invitations SET used_at=UTC_TIMESTAMP() WHERE id=?',[$invite['id']]);$role=Database::query($p,"SELECT id FROM training_participation_roles WHERE programme_id=? AND code='participant'",[$id])->fetchColumn();Database::query($p,'INSERT IGNORE INTO training_participation_assignments(registration_id,role_id,assigned_by) VALUES(?,?,?)',[$reg['id'],$role,$u]);return (int)$reg['id'];
  });
 }
 public static function decide(\PDO $p,int $u,int $programme,int $rid,string $decision,string $reason):void {
  Core::tx($p,function()use($p,$u,$programme,$rid,$decision,$reason){$r=Policy::programme($p,$programme,true);$reg=Database::query($p,'SELECT * FROM training_registrations WHERE id=? AND programme_id=? FOR UPDATE',[$rid,$programme])->fetch();if(!$reg)throw new \RuntimeException('Pendaftaran tidak wujud.');$actor=Policy::actor($p,$u);$self=(int)$actor['staff_identity_id']===(int)$reg['staff_identity_id'];
   if($decision==='WITHDRAW'){if(!$self)Policy::require($p,$u,'participants.manage',$r);if(!in_array($reg['status'],['PENDING','CONFIRMED','WAITLISTED'],true))throw new \RuntimeException('Pendaftaran tidak aktif.');$to='WITHDRAWN';}
   else{Policy::require($p,$u,'participants.manage',$r);if($reg['status']!=='PENDING'||!in_array($decision,['APPROVE','REJECT'],true)||$r['is_cancelled'])throw new \RuntimeException('Permohonan bukan pending.');$to=$decision==='APPROVE'?'CONFIRMED':'REJECTED';if($to==='CONFIRMED'){if(!Database::query($p,'SELECT 1 FROM users WHERE staff_identity_id=? AND is_active=1',[$reg['staff_identity_id']])->fetchColumn())throw new \RuntimeException('Staf perlu claim akaun dahulu.');self::eligibility($p,$r,Policy::config($p,$r,true),self::snapshot($p,(int)$reg['staff_identity_id']));}}
   self::change($p,$r,$reg,$u,$to,Core::text($reason,500));if(!$r['is_cancelled'])self::promote($p,$u,$r);
  });
 }
 private static function promote(\PDO $p,int $u,array $r):void {
  $c=Policy::config($p,$r,true);if(gmdate('Y-m-d H:i:s')>$c['end_at']||!$r['is_published'])return;
  foreach(Database::query($p,"SELECT * FROM training_registrations WHERE programme_id=? AND status='WAITLISTED' ORDER BY wait_sequence,id FOR UPDATE",[$r['id']])->fetchAll() as $reg){try{$s=self::snapshot($p,(int)$reg['staff_identity_id']);self::eligibility($p,$r,$c,$s);}catch(\RuntimeException $e){continue;}if(!self::available($p,(int)$r['id'],$c,json_decode($reg['snapshot_json'],true,512,JSON_THROW_ON_ERROR)))continue;$account=Database::query($p,'SELECT id FROM users WHERE staff_identity_id=? AND is_active=1',[$reg['staff_identity_id']])->fetchColumn();Database::query($p,'UPDATE training_registrations SET eligibility_json=? WHERE id=?',[json_encode(self::eligibility($p,$r,$c,$s),JSON_THROW_ON_ERROR),$reg['id']]);self::change($p,$r,$reg,$u,$c['approval_mode']==='AUTO'&&$account?'CONFIRMED':'PENDING','Waiting list promotion');}
 }
 public static function preview(\PDO $p,int $u,int $id,string $csv):array {
  $r=Policy::programme($p,$id);Policy::require($p,$u,'participants.assign',$r);if(strlen($csv)>1048576)throw new \InvalidArgumentException('CSV maksimum 1 MB.');$f=fopen('php://temp','w+');fwrite($f,$csv);rewind($f);$head=fgetcsv($f);if($head!==['official_email'])throw new \InvalidArgumentException('CSV memerlukan satu header official_email.');$rows=[];$seen=[];while(($line=fgetcsv($f))!==false){if(count($rows)>=1000)throw new \InvalidArgumentException('Maksimum 1000 baris.');$email=$line[0]??'';$item=['email'=>$email,'staff_identity_id'=>null,'error'=>null];try{if(count($line)!==1)throw new \InvalidArgumentException('Bilangan kolum tidak sah.');$email=Core::email($email);if(isset($seen[$email]))throw new \RuntimeException('Duplicate dalam fail.');$seen[$email]=true;$sid=Database::query($p,'SELECT staff_identity_id FROM staff_profiles WHERE official_email=?',[$email])->fetchColumn();if(!$sid)throw new \RuntimeException('Tiada dalam Shared Staff Registry.');Staff::get($p,$u,(int)$sid);self::eligibility($p,$r,Policy::config($p,$r,true),self::snapshot($p,(int)$sid));$item['staff_identity_id']=(int)$sid;}catch(\RuntimeException|\InvalidArgumentException $e){$item['error']=$e->getMessage();}$rows[]=$item;}fclose($f);return $rows;
 }
 public static function bulk(\PDO $p,int $u,int $id,array $staff):array {
  if(!$staff||count($staff)>1000)throw new \InvalidArgumentException('Pilih 1–1000 staf.');$out=[];foreach(array_unique($staff) as $sid){try{$sid=Core::id($sid);$out[]=['staff'=>$sid,'id'=>self::register($p,$u,$id,$sid,'ADMIN_ASSIGNED'),'status'=>'PASS'];}catch(\RuntimeException|\InvalidArgumentException $e){$out[]=['staff'=>$sid,'status'=>'FAIL','error'=>$e->getMessage()];}}return $out;
 }
}
